package com.fitbite.service;
import com.fitbite.dto.RecipeDtos.*; import com.fitbite.entity.*; import java.util.*;
public final class RecipeMapper {private RecipeMapper(){} public static RecipeSummary summary(Recipe r,boolean fav){return new RecipeSummary(r.getId(),r.getName(),r.getDescription(),r.getCategory()==null?null:r.getCategory().getName(),r.getCuisine(),r.getMealType(),r.getCalories(),r.getProtein(),r.getCarbohydrates(),r.getFat(),r.getFiber(),r.getSodium(),r.getTotalTime(),r.getServings(),r.getDifficulty(),r.getDietaryTags(),r.getHealthTags(),r.getImageUrl(),fav);} public static RecipeDetail detail(Recipe r,boolean fav){return new RecipeDetail(r.getId(),r.getName(),r.getDescription(),r.getCategory()==null?null:r.getCategory().getName(),r.getCuisine(),r.getMealType(),r.getIngredients().stream().map(i->new IngredientView(i.getIngredient().getName(),i.getQuantity())).toList(),r.getSteps(),r.getPreparationTime(),r.getCookingTime(),r.getTotalTime(),r.getServings(),r.getCalories(),r.getProtein(),r.getCarbohydrates(),r.getFat(),r.getFiber(),r.getSodium(),r.getDifficulty(),r.getDietaryTags(),r.getHealthTags(),r.getImageUrl(),r.getNutritionSource(),r.getHealthGoals().stream().map(HealthGoal::getName).sorted().toList(),fav);}}
